import matplotlib.pyplot as plt
import pandas as pd

# Load the CSV file generated by your continuous capture script
csv_filename = "continuous_sensor_log.csv"

try:
  df = pd.read_csv(csv_filename)
except FileNotFoundError:
  print(
      f"Error: Could not find '{csv_filename}'. Make sure you ran the capture"
      " script first!"
  )
  exit()

# Display unique rails found in the log
print("Available rails found:", df["Rail"].unique())

# Set up the plot layout
plt.figure(figsize=(12, 6))

# Loop through each rail and plot its power over the sample index
for rail in df["Rail"].unique():
  rail_data = df[df["Rail"] == rail]
  plt.plot(
      rail_data["Sample_Index"],
      rail_data["Power"],
      label=f"{rail} Power (W)",
      alpha=0.8,
  )

# Customize graph details
plt.xlabel("Sample Index", fontsize=12)
plt.ylabel("Power (Watts)", fontsize=12)
plt.title("PMD2X High-Speed Power Monitoring", fontsize=14)
plt.legend(bbox_to_anchor=(1.05, 1), loc="upper left")
plt.grid(True, linestyle="--", alpha=0.6)
plt.tight_layout()

# Show the interactive plot window
print("Displaying graph...")
plt.show()